var sorter = new Sorter(new ByLength());
Console.WriteLine(string.Join(", ", sorter.Sort(["pear", "fig", "banana"])));

interface IOrdering { int Compare(string a, string b); }
class ByLength : IOrdering { public int Compare(string a, string b) => a.Length - b.Length; }

class Sorter(IOrdering ordering)
{
    public List<string> Sort(List<string> items)
    {
        var copy = new List<string>(items);
        copy.Sort(ordering.Compare);
        return copy;
    }
}

Console.WriteLine(PaymentFactory.Create("card").Pay(50m));
Console.WriteLine(PaymentFactory.Create("cash").Pay(50m));

interface IPayment { string Pay(decimal amount); }
class CardPayment : IPayment { public string Pay(decimal amount) => $"Charged {amount} to card"; }
class CashPayment : IPayment { public string Pay(decimal amount) => $"Collect {amount} in cash"; }

static class PaymentFactory
{
    public static IPayment Create(string method) => method switch
    {
        "card" => new CardPayment(),
        "cash" => new CashPayment(),
        _ => throw new ArgumentException($"Unknown method: {method}"),
    };
}

IPriceService service = new LoggingPriceService(new PriceService());
