    }
}

var order = new Order("Mona");
order.AddLine("Keyboard", 2, 40m);
order.AddLine("Mouse", 1, 15m);
Console.WriteLine($"{order.Customer}: {order.Total}");

record OrderLine(string Product, int Quantity, decimal UnitPrice);

class Order(string customer)
{
    private readonly List<OrderLine> _lines = [];
    public string Customer { get; } = customer;
    public decimal Total => _lines.Sum(l => l.Quantity * l.UnitPrice);

    public void AddLine(string product, int quantity, decimal unitPrice) =>
        _lines.Add(new OrderLine(product, quantity, unitPrice));
}

var task = new TodoItem("Write report");
task.Complete();
Console.WriteLine(task.IsDone);

try { task.Complete(); }
catch (InvalidOperationException ex) { Console.WriteLine(ex.Message); }

class TodoItem(string title)
{
    public string Title { get; } = title;
    public bool IsDone { get; private set; }

    public void Complete()
    {
        if (IsDone) throw new InvalidOperationException("Already completed.");
        IsDone = true;
    }
}

var price = new Money(20m, "USD");
var shipping = new Money(5m, "USD");
Console.WriteLine(price.Add(shipping));
Console.WriteLine(price == new Money(20m, "USD"));

record Money(decimal Amount, string Currency)
{
    public Money Add(Money other)
    {
        if (other.Currency != Currency) throw new InvalidOperationException("Different currencies.");
        return this with { Amount = Amount + other.Amount };
    }
}
